/// Complete private original trust path/resource/options helpers over this
/// owner's genuine filesystem, path, OS, configuration and path utilities.
/// Store/event policy and the full Main runtimeFactory are separate owners.
pub fn createProjectTrustPaths(self: *Owner) !c.JSValue {
    return projectTrustPathsEntry(self);
}

fn projectTrustPathsEntry(self: *Owner) !c.JSValue {
    try self.check();
    const engine = self.engine;
    var invocation: em.Engine.NativeInvocation = .{};
    engine.enterNativeInvocation(&invocation);
    engine.native_exception_diagnostics_suppressed += 1;
    defer engine.native_exception_diagnostics_suppressed -= 1;
    var s: Scope = .{ .engine = engine };
    const result = owned.finishValue(&s, projectTrustPathsBody(self, &s)) catch |err|
        return engine.checked(engine.leaveNativeInvocation(&invocation, sdk.fail(engine, err)));
    return engine.checked(engine.leaveNativeInvocation(&invocation, result));
}
fn projectTrustPathsBody(self: *Owner, s: *Scope) !c.JSValue {
    const core = if (self.auth) |*value| value else return error.ActualSdkApplicationAuthRetired;
    // Snapshot the actual owned runtime before imported Gets can reenter and
    // retire this host handle. No borrowed Owner field is read after that point.
    const runtime = try root(s, c.JS_DupValue(s.engine.context, core.runtime_imports));
    const platform = try get(s, runtime, "platform");
    const filesystem = try get(s, platform, "filesystem");
    const paths = try get(s, platform, "paths");
    const os = try builtinDefault(s, "node:os");
    const path_utilities = try get(s, platform, "pathUtilities");
    const configuration = try get(s, runtime, "configuration");
    const config_dir = try get(s, configuration, "CONFIG_DIR_NAME");
    return @import("native_sdk_project_trust_paths.zig").create(s.engine, .{
        .filesystem = filesystem, .paths = paths, .os = os,
        .path_utilities = path_utilities, .config_dir = config_dir,
    });
}
